12	/// How the HTTP server obtains its listening socket.
13	#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
14	pub enum HttpListenerMode {
15	    /// Bind a fresh TCP listener on the given host/port.
16	    BindTcp { host: String, port: u16 },
17	    /// Bind a fresh Unix domain listener on the given filesystem path.
18	    BindUnix { path: String },
19	    /// Adopt an already-open listening socket inherited from a supervisor
20	    /// process.
21	    InheritedFd { fd: i32 },
22	}
23	
24	/// Which coordinator implementation should be active when one is present for a
25	/// frontend client.
26	#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
27	pub enum CoordinatorMode {
28	    /// Do not run a coordinator at all.
29	    None,
30	    /// Run the Rust in-process coordinator for managed `serve` deployments, if
31	    /// there are multiple engines and the model is MoE.
32	    MaybeInProc,
33	    /// Connect to an external coordinator owned by another process.
34	    External { address: String },
35	}
36	
37	/// HTTP/API-server behavior switches that affect route-layer responses.
38	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Default)]
39	pub struct ApiServerOptions {
40	    /// Log a summary line for each completed request.
41	    pub enable_log_requests: bool,
42	    /// When `true`, include prompt token cache details in response usage.
43	    pub enable_prompt_tokens_details: bool,
44	    /// When `true`, set `X-Request-Id` on every HTTP response.
45	    pub enable_request_id_headers: bool,
46	}
