110	/// The server owns one `vllm-chat` facade, which in turn owns the lower
111	/// `vllm-text` and `vllm-llm` layers, and shuts them down before returning.
112	pub async fn serve(config: Config, shutdown: CancellationToken) -> Result<()> {
113	    serve_with_router_extension(config, shutdown, |router| router).await
114	}
