/// This layer sits outside authentication so it can answer `OPTIONS` preflight
/// requests without a bearer token and so it can withhold CORS headers from
/// unauthorized (`401`) responses.
pub async fn apply_cors(State(state): State<Arc<AppState>>, req: Request, next: Next) -> Response {
    let cors = state.cors_config().clone();
    let origin = req.headers().get(ORIGIN).cloned();

    // Answer preflight requests directly. A preflight is an `OPTIONS` request
    // carrying an `Origin` header; routes do not otherwise handle `OPTIONS`.
    if req.method() == Method::OPTIONS
        && let Some(origin) = origin.as_ref()
    {
        let requested_headers = req.headers().get(ACCESS_CONTROL_REQUEST_HEADERS).cloned();
        let mut response = Response::new(Body::empty());
        write_preflight_headers(
            response.headers_mut(),
            &cors,
            origin,
            requested_headers.as_ref(),
        );
        return response;
    }

    let mut response = next.run(req).await;

    // Unauthorized responses must not leak CORS headers.
    if response.status() == StatusCode::UNAUTHORIZED {
        return response;
    }

