/// How the `Access-Control-Allow-Origin` header should be resolved for a
/// request carrying the given `Origin`.
enum OriginDecision {
    /// The origin is not allowed; emit no origin headers.
    Denied,
    /// Emit `Access-Control-Allow-Origin: *`.
    Wildcard,
    /// Reflect the request origin and add `Vary: origin`.
    Mirror,
}

fn resolve_origin(cors: &CorsConfig, origin: &HeaderValue) -> OriginDecision {
    let allow_all = cors.allow_origins.iter().any(|value| value == WILDCARD);
    if allow_all {
        // A wildcard origin cannot be combined with credentials, so reflect the
        // request origin instead when credentials are enabled.
        if cors.allow_credentials {
            OriginDecision::Mirror
        } else {
            OriginDecision::Wildcard
        }
    } else if origin
        .to_str()
        .is_ok_and(|origin| cors.allow_origins.iter().any(|allowed| allowed == origin))
