fn write_preflight_headers(
    headers: &mut HeaderMap,
    cors: &CorsConfig,
    origin: &HeaderValue,
    requested_headers: Option<&HeaderValue>,
) {
    write_origin_headers(headers, cors, origin);

    let methods = if cors.allow_methods.iter().any(|value| value == WILDCARD) {
        ALL_METHODS.to_string()
    } else {
        cors.allow_methods.join(",")
    };
    if let Ok(value) = HeaderValue::from_str(&methods) {
        headers.insert(ACCESS_CONTROL_ALLOW_METHODS, value);
    }

    if cors.allow_headers.iter().any(|value| value == WILDCARD) {
        // Mirror the requested headers verbatim when any header is allowed.
        if let Some(requested_headers) = requested_headers {
            headers.insert(ACCESS_CONTROL_ALLOW_HEADERS, requested_headers.clone());
        }
    } else {
        // Union the explicit allowlist with the CORS safelist, lowercased and
        // sorted for a deterministic header value.
        let mut allowed: BTreeSet<String> =
            SAFELIST_HEADERS.iter().map(|header| header.to_string()).collect();
        allowed.extend(cors.allow_headers.iter().map(|header| header.to_ascii_lowercase()));
        let joined = allowed.into_iter().collect::<Vec<_>>().join(",");
        if let Ok(value) = HeaderValue::from_str(&joined) {
            headers.insert(ACCESS_CONTROL_ALLOW_HEADERS, value);
        }
    }

    if cors.allow_credentials {
        headers.insert(
            ACCESS_CONTROL_ALLOW_CREDENTIALS,
            HeaderValue::from_static("true"),
        );
    }
}
