/// Wildcard marker used in origin/method/header allowlists.
const WILDCARD: &str = "*";

/// Explicit HTTP verbs advertised when `allow_methods` is a wildcard.
///
/// Mirrors the Python server, which expands `["*"]` to the full method set in
/// preflight responses. Kept sorted so the emitted header is deterministic.
const ALL_METHODS: &str = "DELETE,GET,HEAD,OPTIONS,PATCH,POST,PUT";

/// CORS-safelisted request-header names (lowercased) that are always advertised
/// alongside any explicitly configured `allow_headers` entries.
const SAFELIST_HEADERS: &[&str] =
    &["accept", "accept-language", "content-language", "content-type"];

/// Apply Cross-Origin Resource Sharing headers, mirroring the permissive
/// defaults of the Python vLLM server.
///
/// This layer sits outside authentication so it can answer `OPTIONS` preflight
/// requests without a bearer token and so it can withhold CORS headers from
/// unauthorized (`401`) responses.
pub async fn apply_cors(State(state): State<Arc<AppState>>, req: Request, next: Next) -> Response {
    let cors = state.cors_config().clone();
    let origin = req.headers().get(ORIGIN).cloned();

    // Answer preflight requests directly. A preflight is an `OPTIONS` request
    // carrying an `Origin` header; routes do not otherwise handle `OPTIONS`.
    if req.method() == Method::OPTIONS
        && let Some(origin) = origin.as_ref()
    {
        let requested_headers = req.headers().get(ACCESS_CONTROL_REQUEST_HEADERS).cloned();
        let mut response = Response::new(Body::empty());
        write_preflight_headers(
            response.headers_mut(),
            &cors,
            origin,
            requested_headers.as_ref(),
        );
        return response;
    }

    let mut response = next.run(req).await;

    // Unauthorized responses must not leak CORS headers.
    if response.status() == StatusCode::UNAUTHORIZED {
        return response;
    }

    if let Some(origin) = origin.as_ref() {
        write_simple_headers(response.headers_mut(), &cors, origin);
    }

    response
}

/// How the `Access-Control-Allow-Origin` header should be resolved for a
/// request carrying the given `Origin`.
enum OriginDecision {
    /// The origin is not allowed; emit no origin headers.
    Denied,
    /// Emit `Access-Control-Allow-Origin: *`.
    Wildcard,
    /// Reflect the request origin and add `Vary: origin`.
    Mirror,
}

fn resolve_origin(cors: &CorsConfig, origin: &HeaderValue) -> OriginDecision {
    let allow_all = cors.allow_origins.iter().any(|value| value == WILDCARD);
    if allow_all {
        // A wildcard origin cannot be combined with credentials, so reflect the
        // request origin instead when credentials are enabled.
        if cors.allow_credentials {
            OriginDecision::Mirror
        } else {
            OriginDecision::Wildcard
        }
    } else if origin
        .to_str()
        .is_ok_and(|origin| cors.allow_origins.iter().any(|allowed| allowed == origin))
    {
        OriginDecision::Mirror
    } else {
        OriginDecision::Denied
    }
}

/// Write origin-related headers shared by simple and preflight responses.
fn write_origin_headers(headers: &mut HeaderMap, cors: &CorsConfig, origin: &HeaderValue) {
    match resolve_origin(cors, origin) {
        OriginDecision::Denied => {}
        OriginDecision::Wildcard => {
            headers.insert(ACCESS_CONTROL_ALLOW_ORIGIN, HeaderValue::from_static(WILDCARD));
        }
        OriginDecision::Mirror => {
            headers.insert(ACCESS_CONTROL_ALLOW_ORIGIN, origin.clone());
            headers.insert(VARY, HeaderValue::from_static("origin"));
            if cors.allow_credentials {
                headers.insert(
                    ACCESS_CONTROL_ALLOW_CREDENTIALS,
                    HeaderValue::from_static("true"),
                );
            }
        }
    }
}

